\title{Density Meets Incompressibility:\\ The EML Complexity Price of Universal Approximation}
\author{Aristotle}
\date{2026-06-28}

\begin{document}
\maketitle

\begin{abstract}
We study the \textbf{EML class} --- the family of real functions generated from
the identity $x \mapsto x$ by addition, multiplication, exponentiation
$t \mapsto e^{t}$, and logarithm $t \mapsto \log t$, with \emph{no constant
leaves}. We connect two seemingly opposed properties. Qualitatively, finite real
linear combinations of the exponential monomials $x \mapsto e^{kx}$ are uniformly
dense in $C([a,b])$, so the EML class is a universal approximator.
Quantitatively, we introduce a Kolmogorov-style complexity measure $K$ on
EML-computable functions --- the size of the smallest generating term --- and
observe that, the alphabet being finite, every fixed size budget $n$ yields only
\emph{finitely many} representable functions. We reconcile these by constructing
an explicit infinite, injective, EML-computable family of generators
$\expBasis(k)$ computing $x \mapsto e^{(k+1)x}$, with exact size $2k+2$, hence
$K(x \mapsto e^{(k+1)x}) \le 2k+2$. Because each budget is a finite island while
the dense family is infinite and injective, the family escapes every finite
complexity island; universal approximation is realized by an EML-computable
family whose complexity is unbounded across the family. We isolate the constant
$1 = e^{0\cdot x}$ as the unique density generator outside the constant-free
class. We close with numerical experiments and falsifiable conjectures, including
a conjectured matching lower bound $K(e^{kx}) = \Theta(k)$ and a depth--accuracy
law.
\end{abstract}

\textbf{Keywords:} EML class, universal approximation, Kolmogorov complexity,
exponential monomials, Stone--Weierstrass, density, incompressibility, term
algebra.

\section{Introduction}
Two desiderata pull against each other whenever functions are represented by
formulas. \emph{Expressiveness} asks that the class approximate any target;
\emph{parsimony} asks that individual representations be short. Universal
approximation theory (Stone--Weierstrass and descendants) addresses the first;
descriptive complexity (Kolmogorov, Solomonoff, Chaitin) the second. This paper
makes their interaction precise for a concrete, finitely-generated class.

The \textbf{EML class} (Exponential--Multiplicative--Logarithmic) is the closure
of the identity under $+$, $\times$, $\exp$, and $\log$. It abstracts the analytic
primitives recurring throughout scientific computing and machine learning.
Restricting to a \emph{constant-free} algebra makes the syntactic class countable
and the complexity theory clean. Our contributions are: (1) a Kolmogorov measure
$K$ for EML with a Finiteness Principle; (2) an explicit dense, EML-computable
generator family with the linear bound $K(e^{(k+1)x}) \le 2k+2$; (3) the synthesis
that density and EML-computability coexist with unbounded across-family
complexity; and (4) the boundary result isolating the constant $1$ as the unique
missing primitive. Names in typewriter font are the formally verified theorem
identifiers.

\section{The EML term algebra}

\begin{definition}[EML terms]
The set $\ETerm$ of \emph{constant-free EML terms} is generated inductively by: a
leaf $\var$; binary constructors $\mathsf{add}(s,t)$, $\mathsf{mul}(s,t)$; and
unary constructors $\mathsf{expOf}(t)$, $\mathsf{logOf}(t)$. The alphabet is
finite and there are no numeric leaves, so $\ETerm$ is countable with finitely
many terms of each size.
\end{definition}

\begin{definition}[Semantics]
The evaluation map $\eval : \ETerm \to (\R \to \R)$ satisfies
$\eval(\var)(x) = x$, $\eval(s+t)(x) = \eval(s)(x) + \eval(t)(x)$,
$\eval(s \times t)(x) = \eval(s)(x)\,\eval(t)(x)$,
$\eval(\mathsf{expOf}\,t)(x) = e^{\eval(t)(x)}$, and
$\eval(\mathsf{logOf}\,t)(x) = \log \eval(t)(x)$.
\end{definition}

\begin{definition}[Size and depth]
The size $|t|$ counts leaves and operators: $|\var| = 1$, $|s \star t| = |s| +
|t| + 1$ for binary $\star$, $|{\circ}\,t| = |t| + 1$ for unary $\circ$. The depth
$d(t)$ is $0$ for $\var$, $\max(d(s),d(t))+1$ for binary nodes, $d(t)+1$ for unary
nodes.
\end{definition}

\begin{definition}[EML-computable]
A function $g : \R \to \R$ is \emph{EML-computable}, $\IsEMLComputable(g)$, if
$\eval(t) = g$ for some $t \in \ETerm$.
\end{definition}

\begin{definition}[EML complexity]
For EML-computable $g$, $\Kc(g) = \min\{\,|t| : t \in \ETerm,\ \eval(t) = g\,\}$.
If $\eval(t) = g$ then $\Kc(g) \le |t|$ (\texttt{K\_le\_of\_eval}).
\end{definition}

\begin{definition}[Budget islands]
For $n \in \N$, $\computableLE(n) = \{\, g : g \text{ EML-computable},\ \Kc(g) \le
n \,\}$.
\end{definition}

\begin{proposition}[Finiteness Principle, \texttt{finite\_computableLE}]
For every $n$, $\computableLE(n)$ is finite.
\end{proposition}
\begin{proof}[Proof sketch]
There are finitely many terms of size $\le n$ (a finite alphabet admits finitely
many syntax trees of bounded size), and $\eval$ maps this finite set onto
$\computableLE(n)$; the image of a finite set is finite.
\end{proof}

\section{The qualitative side: density}
Let $[a,b] \subset \R$ be compact and $C([a,b],\R)$ the Banach space of
continuous functions with the uniform norm. Write $\operatorname{iccCoord}(a,b)$
for the coordinate map $[a,b] \hookrightarrow \R$ (injective for $a<b$,
\texttt{injective\_iccCoord}) and $\operatorname{expCM}$ for $x \mapsto e^{x}$.

\begin{theorem}[Exponential monomial density, \texttt{exp\_monomials\_span\_dense}]
For an injective continuous feature $g : X \to \R$ on a compact space $X$, the
linear span of $\{(e^{g})^k : k \in \N\}$ is dense in $C(X,\R)$. In particular on
$[a,b]$,
\[
\overline{\operatorname{span}_{\R}\{\, x \mapsto e^{kx} : k \in \N \,\}}
= C([a,b], \R).
\]
\end{theorem}
\begin{proof}[Proof sketch]
The subalgebra generated by $e^{g}$ separates points (as $g$ and $\exp$ are
injective) and contains the constants, so by Stone--Weierstrass it is uniformly
dense. The closure of the subalgebra equals the closure of the span of the powers
$(e^{g})^k$, since powers of one generator span the generated algebra.
\end{proof}

\section{The generators: explicit construction and exact cost}

\begin{definition}[\texttt{repAdd}]
$\repAdd(0) = \var$ and $\repAdd(k+1) = \mathsf{add}(\var, \repAdd(k))$; thus
$\repAdd(k)$ is the $(k+1)$-fold sum $\var + \cdots + \var$.
\end{definition}

\begin{lemma}[\texttt{repAdd\_eval}]
For all $k, x$: $\eval(\repAdd(k))(x) = (k+1)x$.
\end{lemma}
\begin{proof}[Proof sketch]
Induction on $k$: base $\eval(\var)(x) = x$; step $x + (k+1)x = (k+2)x$.
\end{proof}

\begin{lemma}[\texttt{repAdd\_size}]
$|\repAdd(k)| = 2k+1$.
\end{lemma}
\begin{proof}[Proof sketch]
Induction: each step adds one $\var$ leaf and one $\mathsf{add}$ node, $+2$.
\end{proof}

\begin{definition}[\texttt{expBasis}]
$\expBasis(k) = \mathsf{expOf}(\repAdd(k))$.
\end{definition}

\begin{theorem}[\texttt{expBasis\_eval}]
$\eval(\expBasis(k)) = (x \mapsto e^{(k+1)x})$.
\end{theorem}
\begin{proof}[Proof sketch]
Apply $\exp$ to the previous lemma.
\end{proof}

\begin{theorem}[\texttt{expBasis\_size}]
$|\expBasis(k)| = 2k+2$.
\end{theorem}
\begin{proof}[Proof sketch]
The $\mathsf{expOf}$ node adds $1$ to $|\repAdd(k)| = 2k+1$.
\end{proof}

\begin{corollary}[\texttt{expBasis\_isEMLComputable}]
For each $k$, $x \mapsto e^{(k+1)x}$ is EML-computable, witnessed by
$\expBasis(k)$.
\end{corollary}

\begin{theorem}[Linear complexity bound, \texttt{K\_expBasis\_le}]
For every $k$, $\Kc(x \mapsto e^{(k+1)x}) \le 2k+2$.
\end{theorem}
\begin{proof}[Proof sketch]
\texttt{K\_le\_of\_eval} on the witness $\expBasis(k)$ gives $\Kc(\cdot) \le
|\expBasis(k)| = 2k+2$.
\end{proof}

\begin{theorem}[Injectivity, \texttt{generators\_injective}]
The map $k \mapsto (x \mapsto e^{(k+1)x})$ is injective.
\end{theorem}
\begin{proof}[Proof sketch]
If $e^{(a+1)x} = e^{(b+1)x}$ for all $x$, evaluate at $x=1$ and use injectivity of
$\exp$ and of $\N \hookrightarrow \R$.
\end{proof}

\section{The bridge: escaping finite islands}

\begin{theorem}[Escape from finite islands,
\texttt{finitely\_many\_generators\_per\_budget}]
For every $n$, $\{\, k \in \N : (x \mapsto e^{(k+1)x}) \in \computableLE(n) \,\}$
is finite.
\end{theorem}
\begin{proof}[Proof sketch]
The set is the preimage, under the injective family, of the finite set
$\computableLE(n)$; the preimage of a finite set under an injective map is finite.
\end{proof}

Each island holds finitely many generators, yet the family is infinite; hence
$\sup_k \Kc(x \mapsto e^{(k+1)x}) = \infty$ --- complexity across the family is
unbounded.

\begin{theorem}[Synthesis, \texttt{dense\_and\_generators\_EMLcomputable}]
For every compact $[a,b]$: (1) the linear span of
$\{(\operatorname{expCM} \circ \operatorname{iccCoord}(a,b))^k : k \in \N\}$ is
dense in $C([a,b],\R)$; and (2) for every $k$, $x \mapsto e^{(k+1)x}$ is
EML-computable.
\end{theorem}
\begin{proof}[Proof sketch]
Conjunct (1) is the density theorem specialized to the injective coordinate map;
conjunct (2) is the corollary above. Together they give universal approximation by
an EML-computable family with member-wise linear and across-family unbounded
complexity.
\end{proof}

\section{The boundary: the missing constant}

\begin{observation}[Unique missing generator]
The single density generator the constant-free EML class cannot represent is
$x \mapsto e^{0\cdot x} = 1$, the constant function $1$.
\end{observation}

Every $\ETerm$ propagates the input through total operations and has no numeric
leaf, so no constant is EML-computable; yet Stone--Weierstrass requires a unital
subalgebra. The boundary is exactly one object wide: adding a leaf $\mathsf{one}$
with $\eval = 1$ closes the gap.

\section{Future directions}

\begin{conjecture}[One bit of incompressible information]
Extend the algebra with a leaf $\mathsf{one}$ ($\eval = 1$). For rational
constants $c_q : x \mapsto q$, $\Kc(c_q)$ is finite for every $q \in \Q$ but
$\sup_q \Kc(c_q) = \infty$; the constant-free class computes no constant.
\end{conjecture}

\begin{conjecture}[Matching lower bound]
$\Kc(e^{(k+1)x}) \ge c\,k$ for some $c > 0$, so $\Kc(e^{kx}) = \Theta(k)$. A
size-$s$ term has bounded exponential frequency content, forcing size growth in
$k$.
\end{conjecture}

\begin{conjecture}[Depth--accuracy law]
For fixed real-analytic $f$ on $[a,b]$, the minimal EML depth for uniform
$\varepsilon$-approximation grows like $\log\log(1/\varepsilon)$, via
$e^{n\log x} = x^n$ at constant depth and balanced add/mul assembly with the
size--depth tower $|t|+1 \le 2^{d(t)+1}$.
\end{conjecture}

\begin{conjecture}[Counting law]
$|\computableLE(n)|$ grows like a fixed exponential in $n$.
\end{conjecture}

\section{Discussion and conclusion}
Density is a statement about the union $\bigcup_n \computableLE(n)$;
incompressibility about each finite stage $\computableLE(n)$. The exponential
generators witness that the union is infinite-dimensional while every stage is
finite --- the precise mechanism by which universal approximation and Kolmogorov
incompressibility coexist. The explicit family $\expBasis(k)$ computing
$e^{(k+1)x}$ with size $2k+2$ is dense, injective, EML-computable, and escapes
every finite island, giving $\Kc(e^{(k+1)x}) \le 2k+2$ with unbounded supremum,
while the constant $1$ marks a one-primitive boundary. This is the formal content
of EML universal approximation with a provable complexity price.

\end{document}

