from __future__ import annotations
from dataclasses import dataclass
from math import exp


@dataclass(frozen=True)
class ETerm:
    kind: str
    left: "ETerm | None" = None
    right: "ETerm | None" = None


def var() -> ETerm:
    return ETerm("var")


def add(s: ETerm, t: ETerm) -> ETerm:
    return ETerm("add", s, t)


def exp_of(t: ETerm) -> ETerm:
    return ETerm("exp", t)


def eval_term(t: ETerm, x: float) -> float:
    if t.kind == "var":
        return x
    if t.kind == "add":
        return eval_term(t.left, x) + eval_term(t.right, x)
    if t.kind == "exp":
        return exp(eval_term(t.left, x))
    raise ValueError(t.kind)


def size(t: ETerm) -> int:
    if t.kind == "var":
        return 1
    if t.kind in ("add", "mul"):
        return size(t.left) + size(t.right) + 1
    return size(t.left) + 1


def rep_add(k: int) -> ETerm:
    t = var()
    for _ in range(k):
        t = add(var(), t)
    return t


def exp_basis(k: int) -> ETerm:
    return exp_of(rep_add(k))


def main() -> None:
    x = 0.7
    print(f"{'k':>3} | {'size':>5} | {'2k+2':>5} | {'eval':>12} | {'e^{(k+1)x}':>12} | ok")
    for k in range(9):
        t = exp_basis(k)
        got, want = eval_term(t, x), exp((k + 1) * x)
        ok = size(t) == 2 * k + 2 and abs(got - want) < 1e-9
        print(f"{k:>3} | {size(t):>5} | {2*k+2:>5} | {got:>12.6f} | {want:>12.6f} | {ok}")


if __name__ == "__main__":
    main()

from __future__ import annotations
from math import exp, cos, pi
from typing import Callable, List, Tuple


def design_matrix(xs: List[float], k_max: int) -> List[List[float]]:
    return [[exp(k * x) for k in range(k_max + 1)] for x in xs]


def solve_normal_equations(A: List[List[float]], y: List[float]) -> List[float]:
    n = len(A[0])
    ata = [[sum(A[r][i] * A[r][j] for r in range(len(A))) for j in range(n)]
           for i in range(n)]
    aty = [sum(A[r][i] * y[r] for r in range(len(A))) for i in range(n)]
    M = [row[:] + [aty[i]] for i, row in enumerate(ata)]
    for col in range(n):
        piv = max(range(col, n), key=lambda r: abs(M[r][col]))
        M[col], M[piv] = M[piv], M[col]
        pivot = M[col][col]
        if abs(pivot) < 1e-15:
            continue
        for r in range(n):
            if r != col:
                factor = M[r][col] / pivot
                for c in range(col, n + 1):
                    M[r][c] -= factor * M[col][c]
    return [M[i][n] / M[i][i] if abs(M[i][i]) > 1e-15 else 0.0 for i in range(n)]


def approximate(target: Callable[[float], float], a: float, b: float,
                k_max: int, n_samples: int = 200) -> Tuple[List[float], float]:
    xs = [a + (b - a) * i / (n_samples - 1) for i in range(n_samples)]
    ys = [target(x) for x in xs]
    coeffs = solve_normal_equations(design_matrix(xs, k_max), ys)
    err = max(abs(sum(coeffs[k] * exp(k * x) for k in range(k_max + 1)) - target(x))
              for x in xs)
    return coeffs, err


def main() -> None:
    targets: List[Tuple[str, Callable[[float], float]]] = [
        ("cos(3 pi x)", lambda x: cos(3 * pi * x)),
        ("|x - 0.5|", lambda x: abs(x - 0.5)),
        ("x^2 - x", lambda x: x * x - x),
    ]
    for name, f in targets:
        print(f"target {name} on [0,1]")
        for k_max in (2, 4, 6, 8, 10):
            _, err = approximate(f, 0.0, 1.0, k_max)
            print(f"  monomials={k_max + 1:>3}  max error = {err:.3e}")
        print()


if __name__ == "__main__":
    main()

